class MaximumAttemptLimitReached(Exception):
    """
    Raised when maximum number of attempts is exceeded
    """
    pass


class WFTError(Exception):
    """ Raised whenever BuildEndpoint encounters an error. """
    pass


class IncorrectBTSType(Exception):
    """
    Raised when given BTS type is neither GNB nor ENB
    """
    pass


class NotSupportedOperation(Exception):
    """
    Raised when BTS operation is not supported
    """
    pass


class MissingObjectError(Exception):
    """
    Raised when object is missing
    """
    pass
